css:
.loader {
  position: relative;
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background:
    radial-gradient(circle, #6366f1 0 30%, transparent 31%),
    repeating-radial-gradient(circle, #111827 0 2px, #1f2937 2px 4px);
  animation: spin 1.6s linear infinite;
}
.loader::before {
  content: "";
  position: absolute;
  top: 12px;
  left: 50%;
  width: 5px;
  height: 5px;
  margin-left: -2.5px;
  border-radius: 50%;
  background: #ffffff;
}
.loader::after {
  content: "";
  position: absolute;
  top: 50%;
  left: 50%;
  width: 4px;
  height: 4px;
  margin: -2px 0 0 -2px;
  border-radius: 50%;
  background: #111827;
  box-shadow: 0 0 0 2px #ffffff;
}
@keyframes spin { to { transform: rotate(360deg); } }
